// [Blur2PC][macOS] Actual original PC motion-blur chain with a GPU-generated window stencil mask.
#include <display.h>
#include <display/buffer/VertexDeclarations.h>
#include <display/window/Window.h>
#include <render/postprocess/Manager.h>
#include <render/utils/Globals.h>
#include <effect/postprocess/motionblur/MotionBlurReduced.h>
#include <system/serialise.h>
#include <system/serialise/macos/NativeFile.h>
#include <cstring>
#include <iostream>
#include <stdexcept>
static void require(bool value,const char* why){if(!value){std::cerr<<why<<std::endl;throw std::runtime_error(why);}}
static void maskPixels(const Display::C_Texture2D& texture){auto p=texture.LockRect2D(0,16);require(p.pBits,"Actual window mask GPU readback unavailable");bool valid=true;for(U32 y=0;y<texture.GetHeight();++y)for(U32 x=0;x<texture.GetWidth();++x){U32 actual;std::memcpy(&actual,p.pBits+y*p.pitch+x*4,4);valid&=(actual&0xffffff)==(x<texture.GetWidth()/2?0xffffff:0);}texture.UnlockRect2D(0);require(valid,"Window mask did not contain the actual left-half 0xff GPU stencil");}
int main(int argc,char** argv){try{
    using namespace Display;require(argc==2,"Expected application source-built shader resource directory");auto& fs=Sys::C_FileSystem::Instance();Sys::SetDefaultFileSystem(&fs);require(fs.SetWorkingDirectory(argv[1]),"Motion blur source-built filesystem failed");C_Device device;device.AddWindow(Maths::C_Rect(Maths::HVec2(0,0),Maths::HVec2(1,1)));C_DeviceParams params;params.m_Width=64;params.m_Height=32;require(device.Create(params)&&device.CreateVolatile(params),"Motion blur real window/device initialization failed");CreateVertexDeclarations();CreateVertexShaders();CreatePixelShaders();C_View view;C_ViewSetup setup;device.SetupView(&view,setup);device.SetupView(&view,setup);
    C_Texture2D depth;require(device.CreateTexture2D(1,1,1,E_Usage_Managed,E_Format_R32F,&depth),"Original window depth allocation failed");auto locked=depth.Lock(0);require(locked.pBits,"Original window depth map failed");const F32 farDepth=1;std::memcpy(locked.pBits,&farDepth,4);depth.Unlock(0);auto* window=device.GetWindow(0);window->m_pDepthTexture=&depth;C_PixelShader downsample;require(Display::CreatePixelShaderFromFile("Shaders/psMotionBlurDownsampleStencil",0,&downsample),"Actual source-built stencil downsample shader absent");C_RenderTexture2D maskCopy;require(device.CreateRenderTexture2D(32,16,1,E_Usage_Colour,E_Format_A8R8G8B8,E_Multisample_None,nullptr,&maskCopy),"Actual stencil downsample output allocation failed");
    {PostProcess::C_Manager post;post.ReserveView(64,32);require(post.AddView(64,32,0,PostProcess::E_RenderTargetFormat_RGBA_U8,E_Multisample_None,2),"Original motion blur manager view failed");auto* motion=new PostProcess::C_MotionBlurReduced(post);motion->SetComposite(false);motion->SetTextureBuffer(nullptr,motion->GetTextureBufferRequiredSize());require(post.Create()&&post.CreateVolatile(),"Original motion blur shaders/resources could not be created");
        for(U32 pass=0;pass<2;++pass){require(device.BeginScene(),"Original motion blur scene failed");device.SetWindow(0);device.SetView(&view);auto& context=device.GetDisplay2().GetContext();context.SetViewport(Display2::C_Viewport(0,0,32,32));context.Clear(Display2::E_Clear_Stencil,0,1,0xff);context.SetViewport(Display2::C_Viewport(0,0,64,32));Quad::DrawFullScreenColour(pass?Maths::C_RGBA_F32(0,1,0,1):Maths::C_RGBA_F32(1,0,0,1));device.RenderWindowMask();device.EndWindow();Render::SetGlobalColourBuffer(window->GetColourTexture());Render::SetGlobalDepthStencilBuffer(window->GetDepthStencilTexture());Render::SetGlobalStencilBuffer(window->GetMaskTexture());device.SetColourDepthStencilSurface();device.SetView(&view);post.Begin(0,view.GetViewport());device.RestoreWindow(0);require(post.GetChainTexture()==nullptr||post.GetChainTexture()->IsCreated(),"Original manager held invalid previous chain state");motion->Display();require(post.GetChainTexture()&&post.GetChainTexture()->IsCreated(),"Original PC motion blur SetViewport did not publish the real scene chain");post.End();device.EndScene();maskPixels(*Render::GetGlobalStencilBuffer());auto* output=motion->GetTexture();require(output&&output->GetWidth()==32&&output->GetHeight()==16,"Original motion blur half-resolution output absent");auto pixels=output->LockRect2D(0,16);require(pixels.pBits,"Original motion blur GPU output unavailable");bool good=true;U32 coloured=0;for(U32 y=0;y<16;++y)for(U32 x=0;x<32;++x){const U8* p=pixels.pBits+y*pixels.pitch+x*4;good&=p[pass?2:1]<=1&&p[0]<=1;if(p[pass?1:2]>250)++coloured;good&=p[3]<=1;}output->UnlockRect2D(0);require(good&&coloured==512,"Original stationary motion blur did not preserve current scene colour/zero motion alpha");
            require(device.BeginScene(),"Actual stencil downsample probe scene failed");device.SetColourDepthStencilSurface(&maskCopy.GetSurface(),nullptr);device.SetCullMode(E_CullMode_None);device.SetDepthEnable(E_Bool_False);device.SetAlphaTestEnable(E_Bool_False);device.SetBlendMode(E_BlendMode_Solid);device.SetColourWriteEnable(E_ColourWriteEnable_All);device.SetTexture(0,post.GetChainTexture());device.SetTexture(1,Render::GetGlobalStencilBuffer());device.SetTextureAddress(0,E_TextureAddress_Clamp);device.SetTextureAddress(1,E_TextureAddress_Clamp);device.SetTextureFilter(0,E_TextureFilter_Linear);device.SetTextureFilter(1,E_TextureFilter_Linear);device.SetPixelShader(&downsample);Quad::DrawFullScreen();device.SetColourDepthStencilSurface();device.EndScene();maskCopy.Resolve();auto mask=maskCopy.GetTexture().LockRect2D(0,16);require(mask.pBits,"Actual stencil downsample GPU pixels unavailable");bool exact=true;for(U32 y=0;y<16;++y)for(U32 x=0;x<32;++x){const U8* p=mask.pBits+y*mask.pitch+x*4;exact&=p[pass?1:2]==255&&p[pass?2:1]==0&&p[0]==0;if(x<15)exact&=p[3]>=254;else if(x>16)exact&=p[3]<=1;}maskCopy.GetTexture().UnlockRect2D(0);require(exact,"Original stencil downsample did not read actual mask red into alpha independently of mask alpha");}
        post.DestroyVolatile();post.Destroy();}
    Render::SetGlobalColourBuffer(nullptr);Render::SetGlobalDepthStencilBuffer(nullptr);Render::SetGlobalStencilBuffer(nullptr);window->m_pDepthTexture=nullptr;device.Destroy(&maskCopy);device.Destroy(&downsample);device.Destroy(&depth);DestroyPixelShaders();DestroyVertexShaders();require(device.GetDisplay2().WaitIdle(),"Original motion blur GPU completion failed");device.DestroyVolatile();device.Destroy();Sys::SetDefaultFileSystem(nullptr);std::cout<<"Original PC motion blur: real per-window stencil->mask GPU pixels, current scene chain publication, source-built motion shaders, actual stencil-red-to-alpha downsample, stationary half-resolution colour/zero-motion alpha across two frames and global/resource teardown PASS\n";return 0;
}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
